function Nav(){var sidenav=document.getElementById("mySidenav"),marginRight=window.getComputedStyle(sidenav).getPropertyValue("margin-right"),btn=document.getElementById("btn-sidebar");"-350px"===marginRight||""===marginRight?(sidenav.style.marginRight="0px",btn.className=btn.className.replace("btn-sidebar-light","btn-sidebar-dark")):(sidenav.style.marginRight="-350px",btn.className=btn.className.replace("btn-sidebar-dark","btn-sidebar-light"))}function flipCard(button){var card=button.parentNode.parentNode;card.classList.contains("card-flipped")?(card.querySelector("#card_frente").classList.remove("d-none"),card.querySelector("#card_verso").classList.add("d-none"),card.classList.remove("card-flipped")):(card.querySelector("#card_verso").classList.remove("d-none"),card.querySelector("#card_frente").classList.add("d-none"),card.classList.add("card-flipped"))}